Windows


Code
n_win &lt;- nrow(windows)



Windows: 25, each 1 km long by 4 km wide (the last is 0.99 km)
Area covered: 99.9 of 112.5 km². The round end caps beyond the endpoints are not part of any window.
Window 1 is at the Richmond end. Distance along the transect (u, km) is measured from the Richmond endpoint; transect_position() in R/functions.R returns u, the signed lateral offset v, and the window id for any point.

Use the layer control (top right) to choose which value colors the windows; hover a window for all of its values.


Code
to_ll &lt;- function(x) st_transform(x, 4326)
win_ll &lt;- to_ll(windows)
win_ll$label &lt;- sprintf(
  "&lt;b&gt;Window %d&lt;/b&gt; (%.0f–%.0f km)&lt;br&gt;Impervious: %.1f%%&lt;br&gt;Developed: %.1f%%&lt;br&gt;
   Developed, open: %.1f%%&lt;br&gt;Forest: %.1f%%&lt;br&gt;Wetland + water: %.1f%%",
  win_ll$window, win_ll$u_start_km, win_ll$u_end_km, win_ll$imperv_mean, win_ll$developed_pct,
  win_ll$developed_open_pct, win_ll$forest_pct, win_ll$wetland_pct + win_ll$water_pct
)
win_ll$wet_water &lt;- win_ll$wetland_pct + win_ll$water_pct
if (!is.null(ndvi)) {
  win_ll$label &lt;- paste0(win_ll$label, sprintf("&lt;br&gt;Evergreen (NDVI): %.1f%%", win_ll$evg_pct))
}

# One single-hue sequential scale per metric, all on a shared 0-100% domain
metrics &lt;- list(
  "Impervious surface" = list(col = "imperv_mean",   pal = "Purples"),
  "Developed"          = list(col = "developed_pct", pal = "Reds"),
  "Forest"             = list(col = "forest_pct",    pal = "Greens"),
  "Wetland + water"    = list(col = "wet_water",     pal = "Blues")
)
if (!is.null(ndvi)) metrics[["Evergreen (NDVI)"]] &lt;- list(col = "evg_pct", pal = "BuGn")

m &lt;- leaflet(win_ll) |&gt;
  addProviderTiles(providers$Esri.WorldGrayCanvas) |&gt;
  addProviderTiles(providers$Esri.WorldImagery, group = "Imagery")
for (nm in names(metrics)) {
  pal &lt;- colorNumeric(metrics[[nm]]$pal, domain = c(0, 100))
  m &lt;- m |&gt;
    addPolygons(color = "white", weight = 1, fillOpacity = 0.7,
                fillColor = pal(win_ll[[metrics[[nm]]$col]]),
                label = lapply(win_ll$label, htmltools::HTML),
                highlightOptions = highlightOptions(color = "black", weight = 2, bringToFront = TRUE),
                group = nm) |&gt;
    addLegend(pal = pal, values = c(0, 100), title = paste(nm, "(%)"),
              position = "bottomright", className = "info legend metric-legend",
              layerId = nm)
}
m |&gt;
  addPolylines(data = to_ll(line), color = "black", dashArray = "6", weight = 2) |&gt;
  addLayersControl(baseGroups = names(metrics), overlayGroups = "Imagery",
                   options = layersControlOptions(collapsed = FALSE)) |&gt;
  hideGroup("Imagery") |&gt;
  # Leaflet does not hide legends for radio (base) layers; show only the selected metric's
  htmlwidgets::onRender(sprintf("
    function(el, x) {
      var map = this;
      function show(name) {
        el.querySelectorAll('.metric-legend').forEach(function(lg) {
          lg.style.display = lg.textContent.trim().startsWith(name + ' (%%)') ? '' : 'none';
        });
      }
      show(%s);
      map.on('baselayerchange', function(e) { show(e.name); });
    }", jsonlite::toJSON(names(metrics)[1], auto_unbox = TRUE)))

